import clsx from 'clsx';
import { FallbackErrorMessageType } from '~/widgets/fallbacks/ui/fallback-error-message';
import { RefreshButton } from '~/shared/ui/reset-button';

type Props = {
  message: string;
  reset?: () => void;
  type?: FallbackErrorMessageType;
};

export const EmptyList = ({ message, reset, type }: Props) => {
  return (
    <div className="empty">
      <p
        className={clsx('flex', 'flex-auto', 'items-center', 'justify-center', {
          alert: type === FallbackErrorMessageType.Alert,
          error: type === FallbackErrorMessageType.Error,
        })}
      >
        <span>{message}</span>
        {reset && <RefreshButton onClick={reset} />}
      </p>
    </div>
  );
};
